-- =============================================================================
-- VinFast hybrid DB — PostgreSQL 16 schema (transactional side)
-- Nguồn: EERD draw.io của nhóm + database/schema.sql (MySQL cũ) + docs/hybrid-db-plan.html
-- Chạy:  psql -v ON_ERROR_STOP=1 -U $PG_USER -d $PG_DB -f database/postgres/001_schema.sql
--
-- Quy ước:
--   * Id số: BIGINT GENERATED BY DEFAULT AS IDENTITY (seed được phép chèn id cũ,
--     sau đó gọi sync_identity() ở cuối file seed).
--   * product_id / variant_id: VARCHAR, tham chiếu LOGIC sang Mongo
--     products.productID / products.variants.variantId (không có FK, quyết định 1, 2).
--   * ENUM của MySQL -> VARCHAR + CHECK; TINYINT(1) -> BOOLEAN;
--     ON UPDATE CURRENT_TIMESTAMP -> trigger set_updated_at().
--   * Tiền: NUMERIC(15,0) (VND, không có phần lẻ) giống DECIMAL(15,0) cũ.
--   * Index phục vụ truy vấn nằm ở 002_indexes.sql (T2). File này chỉ có
--     PK / UNIQUE / CHECK / FK.
--   * Coupon nằm ở 004_coupons.sql (T4); FK orders.coupon_id được thêm ở đó.
-- =============================================================================

BEGIN;

-- Dùng lại được khi reset: xóa sạch schema public rồi tạo lại.
DROP SCHEMA IF EXISTS public CASCADE;
CREATE SCHEMA public;

-- -----------------------------------------------------------------------------
-- Hàm tiện ích
-- -----------------------------------------------------------------------------
CREATE FUNCTION set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

-- Đồng bộ sequence của các cột IDENTITY sau khi seed chèn id tường minh.
CREATE FUNCTION sync_identity() RETURNS void
LANGUAGE plpgsql AS $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT c.table_name, c.column_name
    FROM information_schema.columns c
    WHERE c.table_schema = 'public' AND c.is_identity = 'YES'
  LOOP
    EXECUTE format(
      'SELECT setval(pg_get_serial_sequence(%L, %L), COALESCE((SELECT max(%I) FROM %I), 0) + 1, false)',
      r.table_name, r.column_name, r.column_name, r.table_name);
  END LOOP;
END;
$$;

-- =============================================================================
-- 1. Users & site basics
-- =============================================================================
CREATE TABLE users (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        VARCHAR(100) NOT NULL,
  email       VARCHAR(150) NOT NULL,
  password    VARCHAR(255) NOT NULL,
  role        VARCHAR(10)  NOT NULL DEFAULT 'member'
              CHECK (role IN ('member', 'admin')),
  avatar      VARCHAR(255),
  is_locked   BOOLEAN      NOT NULL DEFAULT FALSE,
  created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);
-- MySQL cũ so sánh email không phân biệt hoa thường; giữ hành vi đó.
-- User::findByEmail phải dùng: WHERE lower(email) = lower(:email)
CREATE UNIQUE INDEX uq_users_email_lower ON users (lower(email));

CREATE TABLE site_settings (
  id     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  key    VARCHAR(100) NOT NULL UNIQUE,   -- "key" không phải từ khóa cấm trong PG, bỏ backtick
  value  TEXT
);

CREATE TABLE contacts (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        VARCHAR(100) NOT NULL,
  email       VARCHAR(150) NOT NULL,
  phone       VARCHAR(20),
  message     TEXT         NOT NULL,
  status      VARCHAR(10)  NOT NULL DEFAULT 'unread'
              CHECK (status IN ('unread', 'read', 'replied')),
  created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE faq_topics (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        VARCHAR(120) NOT NULL,
  slug        VARCHAR(120) NOT NULL UNIQUE,
  icon_svg    TEXT,
  sort_order  SMALLINT     NOT NULL DEFAULT 0,
  is_active   BOOLEAN      NOT NULL DEFAULT TRUE,
  created_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE faqs (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  topic_id    BIGINT       NOT NULL REFERENCES faq_topics (id) ON DELETE CASCADE,
  question    VARCHAR(500) NOT NULL,
  answer      TEXT         NOT NULL,
  sort_order  SMALLINT     NOT NULL DEFAULT 0,
  is_active   BOOLEAN      NOT NULL DEFAULT TRUE,
  created_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE page_assets (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  page_type   VARCHAR(50)  NOT NULL,
  asset_key   VARCHAR(100) NOT NULL,
  file_path   VARCHAR(255) NOT NULL,
  file_size   INTEGER      NOT NULL DEFAULT 0 CHECK (file_size >= 0),
  mime_type   VARCHAR(50),
  created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
  CONSTRAINT uq_page_asset UNIQUE (page_type, asset_key)   -- đích của ON CONFLICT
);

CREATE TABLE about_awards (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title       VARCHAR(255) NOT NULL,
  award_year  INTEGER      NOT NULL CHECK (award_year BETWEEN 1900 AND 2100),
  image_path  VARCHAR(255) NOT NULL,
  created_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- Bảng `email` cũ (NewsController::subscribe) -> email_subscriptions
CREATE TABLE email_subscriptions (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email       VARCHAR(150) NOT NULL,
  created_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX uq_email_subscriptions_lower ON email_subscriptions (lower(email));

-- =============================================================================
-- 2. News & content
-- =============================================================================
CREATE TABLE news (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title       VARCHAR(300) NOT NULL,
  slug        VARCHAR(320) NOT NULL UNIQUE,
  body        TEXT         NOT NULL,
  catalog     VARCHAR(30)
              CHECK (catalog IN ('Công ty', 'Ô tô điện', 'Xe máy điện')),
  views       INTEGER      NOT NULL DEFAULT 0 CHECK (views >= 0),
  news_state  VARCHAR(20)  NOT NULL DEFAULT 'Hiển thị'
              CHECK (news_state IN ('Hiển thị', 'Ẩn')),
  created_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE news_tags (
  news_id  BIGINT      NOT NULL REFERENCES news (id) ON DELETE CASCADE,
  tags     VARCHAR(50) NOT NULL,
  PRIMARY KEY (news_id, tags)
);

CREATE TABLE news_img_info (
  news_id   BIGINT       NOT NULL REFERENCES news (id) ON DELETE CASCADE,
  img_link  VARCHAR(300) NOT NULL,
  img_des   VARCHAR(300) NOT NULL,
  PRIMARY KEY (news_id, img_link, img_des)
);

-- Bình luận tin tức: giữ nguyên chức năng cũ (quyết định 6).
CREATE TABLE comments (
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id        BIGINT      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  news_id        BIGINT      REFERENCES news (id) ON DELETE CASCADE,
  rating         SMALLINT    NOT NULL DEFAULT 0 CHECK (rating BETWEEN 0 AND 5),
  body           TEXT        NOT NULL,
  helpful_count  INTEGER     NOT NULL DEFAULT 0 CHECK (helpful_count >= 0),
  is_approved    BOOLEAN     NOT NULL DEFAULT FALSE,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- =============================================================================
-- 3. Catalog-adjacent (sản phẩm nằm ở Mongo)
-- =============================================================================

-- Review sản phẩm (COMMENTS_SQL trong EERD) — nguồn chính; Mongo chỉ giữ
-- avgRating, totalReviews và 5 review mới nhất đã duyệt (quyết định 6).
CREATE TABLE product_reviews (
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id        BIGINT      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  product_id     VARCHAR(32) NOT NULL,              -- Mongo products.productID
  rating         SMALLINT    NOT NULL CHECK (rating BETWEEN 1 AND 5),
  body           TEXT        NOT NULL,
  helpful_count  INTEGER     NOT NULL DEFAULT 0 CHECK (helpful_count >= 0),
  is_approved    BOOLEAN     NOT NULL DEFAULT FALSE,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uq_review_user_product UNIQUE (user_id, product_id)   -- 1 review / user / sản phẩm
);

-- Tồn kho: 1 dòng cho mỗi (product_id, variant_id); không theo màu (quyết định 3).
-- Lệnh trừ kho phải kiểm tra (stock - reserved) >= qty.
-- CHECK là chốt chặn cuối: vi phạm -> SQLSTATE 23514 -> OutOfStockException.
CREATE TABLE inventory (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  product_id  VARCHAR(32) NOT NULL,
  variant_id  VARCHAR(64) NOT NULL,
  stock       INTEGER     NOT NULL DEFAULT 0,
  reserved    INTEGER     NOT NULL DEFAULT 0,
  version     INTEGER     NOT NULL DEFAULT 0,       -- optimistic locking (T5)
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uq_inventory_sku     UNIQUE (product_id, variant_id),
  CONSTRAINT ck_inventory_stock   CHECK (stock >= 0),
  CONSTRAINT ck_inventory_reserved CHECK (reserved BETWEEN 0 AND stock)
);

CREATE TABLE test_drives (
  id                     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id                BIGINT       REFERENCES users (id) ON DELETE SET NULL,  -- khách có thể chưa đăng nhập
  name                   VARCHAR(100) NOT NULL,
  email                  VARCHAR(150) NOT NULL,
  phone                  VARCHAR(20)  NOT NULL,
  product_id             VARCHAR(32)  NOT NULL,
  variant_id             VARCHAR(64),
  product_name_snapshot  VARCHAR(200) NOT NULL,   -- thay cho JOIN products (quyết định 14)
  province               VARCHAR(100) NOT NULL,
  showroom               VARCHAR(200) NOT NULL,
  preferred_date         DATE         NOT NULL,
  note                   TEXT,
  status                 VARCHAR(10)  NOT NULL DEFAULT 'pending'
                         CHECK (status IN ('pending', 'confirmed', 'cancelled', 'done')),
  created_at             TIMESTAMPTZ  NOT NULL DEFAULT now(),
  updated_at             TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- =============================================================================
-- 4. Cart & wishlist
-- =============================================================================

-- Mỗi user 1 giỏ (quyết định 12).
CREATE TABLE carts (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id     BIGINT      NOT NULL UNIQUE REFERENCES users (id) ON DELETE CASCADE,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE cart_items (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  cart_id     BIGINT        NOT NULL REFERENCES carts (id) ON DELETE CASCADE,
  product_id  VARCHAR(32)   NOT NULL,
  variant_id  VARCHAR(64)   NOT NULL,
  color_code  VARCHAR(40),                         -- màu chọn trong giỏ; không ảnh hưởng tồn kho
  quantity    INTEGER       NOT NULL DEFAULT 1 CHECK (quantity BETWEEN 1 AND 99),
  unit_price  NUMERIC(15,0) NOT NULL CHECK (unit_price >= 0),   -- giá lúc thêm vào giỏ
  created_at  TIMESTAMPTZ   NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ   NOT NULL DEFAULT now(),
  CONSTRAINT uq_cart_item UNIQUE (cart_id, product_id, variant_id)
);

CREATE TABLE wishlists (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id     BIGINT       NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  name        VARCHAR(100) NOT NULL DEFAULT 'Yêu thích',
  is_public   BOOLEAN      NOT NULL DEFAULT FALSE,
  created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
  CONSTRAINT uq_wishlist_user_name UNIQUE (user_id, name)
);

CREATE TABLE wishlist_items (
  id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  wishlist_id  BIGINT      NOT NULL REFERENCES wishlists (id) ON DELETE CASCADE,
  product_id   VARCHAR(32) NOT NULL,
  variant_id   VARCHAR(64),                        -- NULL = thích cả sản phẩm
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- NULLS NOT DISTINCT (PG15+): không cho 2 dòng (w, p, NULL) trùng nhau
  CONSTRAINT uq_wishlist_item UNIQUE NULLS NOT DISTINCT (wishlist_id, product_id, variant_id)
);

-- =============================================================================
-- 5. Orders
-- =============================================================================
-- Một bảng cho cả hai luồng (quyết định 4):
--   type = 'deposit'  : đặt cọc, đúng 1 item
--   type = 'purchase' : checkout giỏ hàng
-- payment_status là cột thật (quyết định 5); note giữ thông tin form đặt cọc (JSONB).
-- Xóa user có đơn: RESTRICT (giữ lịch sử doanh thu) — cả nhóm cần xác nhận.
CREATE TABLE orders (
  id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id          BIGINT        NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
  type             VARCHAR(10)   NOT NULL DEFAULT 'deposit'
                   CHECK (type IN ('deposit', 'purchase')),
  status           VARCHAR(10)   NOT NULL DEFAULT 'pending'
                   CHECK (status IN ('pending', 'confirmed', 'cancelled', 'done')),
  payment_status   VARCHAR(15)   NOT NULL DEFAULT 'pending_verify'
                   CHECK (payment_status IN ('unpaid', 'pending_verify', 'paid', 'failed', 'refunded')),
  subtotal_amount  NUMERIC(15,0) NOT NULL DEFAULT 0 CHECK (subtotal_amount >= 0),
  discount_amount  NUMERIC(15,0) NOT NULL DEFAULT 0 CHECK (discount_amount >= 0),
  total_amount     NUMERIC(15,0) NOT NULL DEFAULT 0 CHECK (total_amount >= 0),
  coupon_id        BIGINT,                         -- FK thêm ở 004_coupons.sql
  note             JSONB         NOT NULL DEFAULT '{}'::jsonb,
  created_at       TIMESTAMPTZ   NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ   NOT NULL DEFAULT now(),
  CONSTRAINT ck_orders_total CHECK (total_amount = subtotal_amount - discount_amount)
);

CREATE TABLE order_items (
  id                     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id               BIGINT        NOT NULL REFERENCES orders (id) ON DELETE CASCADE,
  product_id             VARCHAR(32)   NOT NULL,
  variant_id             VARCHAR(64)   NOT NULL,
  product_name_snapshot  VARCHAR(200)  NOT NULL,
  variant_name_snapshot  VARCHAR(120)  NOT NULL,
  color_code             VARCHAR(40),
  color_name_snapshot    VARCHAR(120),
  unit_price             NUMERIC(15,0) NOT NULL CHECK (unit_price >= 0),
  quantity               INTEGER       NOT NULL CHECK (quantity > 0),
  subtotal               NUMERIC(15,0) GENERATED ALWAYS AS (unit_price * quantity) STORED
);

-- =============================================================================
-- 6. Trigger updated_at
-- =============================================================================
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'users', 'contacts', 'test_drives', 'carts', 'cart_items', 'orders', 'inventory'
  ] LOOP
    EXECUTE format(
      'CREATE TRIGGER trg_%1$s_updated_at BEFORE UPDATE ON %1$I
         FOR EACH ROW EXECUTE FUNCTION set_updated_at()', t);
  END LOOP;
END;
$$;

COMMIT;
